#!/bin/bash
# Run from the folder containing the src files
cd "$(dirname "$0")" && { SPR="${REPO:-/home/claude/rla-sharp}/data/nba_spreads.json"; [ -f "$SPR" ] && python3 tools/nbaspr.py "$SPR" > nba_spr.js || [ -f nba_spr.js ] || echo "const NBA_SPR={};" > nba_spr.js; } && { [ -f nba_espn.js ] || echo "const NBA_ESPN={games:[],logs:[]};" > nba_espn.js; } && { [ -f nhl_data.js ] || echo 'var NHL_GEN="",NHL_DATE="",NHL_TOM="",NHL_SLATE=[],NHL_NEXT=[],NHL_LATER=[],NHL_TEAM={},NHL_RES=[],NHL_P={},NHL_G={},NHL_INJ={},NHL_H2HP={},NHL_LZ=[],NHL_MODEL=null,NHL_PRES=[],NHL_PRES_D=null,NHL_RECENT=[],NHL_PROPS=[];' > nhl_data.js; } && echo '/* NHL data loads on demand from nhl_data.js (next to index.html) */ var NHL_GEN="",NHL_DATE="",NHL_TOM="",NHL_SLATE=[],NHL_NEXT=[],NHL_LATER=[],NHL_TEAM={},NHL_RES=[],NHL_P={},NHL_G={},NHL_INJ={},NHL_H2HP={},NHL_LZ=[],NHL_MODEL=null,NHL_PRES=[],NHL_PRES_D=null,NHL_RECENT=[],NHL_PROPS=[];' > nhl_stub.js && cat shell_head.html real.js pfr.js h2h_notes.js plogs.js plogs2.js posv.js qb1.js engine.js dataview.js inj.js usage_data.js usage.js market.js adv_data.js adv.js plays.js bets.js calc.js nba_data.js nba_spr.js nba_espn.js nba.js nfl_extra.js nfl_tgt.js nfl_rush.js nhl_stub.js nhl.js xsport.js nflx.js propx.js live.js liveodds.js extras.js app.js ui.js > index.html && { [ -f tools/jsonify.py ] && python3 tools/jsonify.py index.html || true; } && echo "built index.html ($(wc -c < index.html) bytes)"
